@js:(function() {
function asString(value) {
    return value === null || value === undefined ? "" : String(value);
}
function isArray(value) {
    return Object.prototype.toString.call(value) === "[object Array]";
}
function extractItemId(value) {
    var text = asString(value);
    var match = text.match(/[?&]item_id=([^&#]+)/i);
    if (match && match[1]) {
        try { return decodeURIComponent(match[1]); } catch (e) { return match[1]; }
    }
    match = text.match(/\/i([0-9]{6,})(?:\/|$)/i);
    if (match && match[1]) return match[1];
    match = text.match(/\/(\d{6,})(?:\/|$)/);
    return match && match[1] ? match[1] : "";
}
function unwrapResponse(res) {
    if (res && typeof res.body === "function") res = res.body();
    return asString(res);
}
function getImageUri(node) {
    if (!node) return "";
    if (node.data && typeof node.data.web_uri === "string" && node.data.web_uri) return String(node.data.web_uri);
    if (typeof node.web_uri === "string" && node.web_uri) return String(node.web_uri);
    return "";
}
function compareImageKey(a, b) {
    var ma = String(a).match(/(\d+)$/);
    var mb = String(b).match(/(\d+)$/);
    if (ma && mb) return parseInt(ma[1], 10) - parseInt(mb[1], 10);
    a = String(a);
    b = String(b);
    return a < b ? -1 : (a > b ? 1 : 0);
}
function unique(list) {
    var seen = {};
    var out = [];
    var i;
    var value;
    for (i = 0; i < list.length; i++) {
        value = list[i];
        if (value && !seen[value]) {
            seen[value] = true;
            out.push(value);
        }
    }
    return out;
}
function collectDeep(node, list) {
    var key;
    var child;
    if (!node) return;
    if (isArray(node)) {
        for (key = 0; key < node.length; key++) collectDeep(node[key], list);
        return;
    }
    if (typeof node !== "object") return;
    if (typeof node.web_uri === "string" && node.web_uri) {
        list.push(String(node.web_uri));
        return;
    }
    if (node.data && typeof node.data.web_uri === "string" && node.data.web_uri) {
        list.push(String(node.data.web_uri));
        return;
    }
    for (key in node) {
        if (node.hasOwnProperty(key)) {
            child = node[key];
            if (child && typeof child === "object") collectDeep(child, list);
        }
    }
}
function collectImages(payload) {
    var images = [];
    var materials;
    var skeleton;
    var keys;
    var i;
    var key;
    var item;
    var uri;
    if (!payload || typeof payload !== "object") return images;
    materials = payload.materials && typeof payload.materials === "object" ? payload.materials : null;
    skeleton = payload.skeleton && payload.skeleton.data && isArray(payload.skeleton.data) ? payload.skeleton.data : null;
    if (materials && skeleton) {
        for (i = 0; i < skeleton.length; i++) {
            item = skeleton[i];
            key = item && (item.elementInfo || item.key || item.id || item.value);
            if (!key) continue;
            uri = getImageUri(materials[key]);
            if (uri) images.push(uri);
        }
    }
    if (materials && !images.length) {
        keys = [];
        for (key in materials) {
            if (materials.hasOwnProperty(key)) keys.push(key);
        }
        keys.sort(compareImageKey);
        for (i = 0; i < keys.length; i++) {
            uri = getImageUri(materials[keys[i]]);
            if (uri) images.push(uri);
        }
    }
    if (!images.length) collectDeep(payload, images);
    return unique(images);
}
var currentUrl = "";
if (typeof chapter !== "undefined" && chapter && chapter.url) currentUrl = String(chapter.url);
if (!currentUrl && typeof baseUrl !== "undefined" && baseUrl) currentUrl = String(baseUrl);
var itemId = extractItemId(currentUrl);
if (!itemId && typeof baseUrl !== "undefined" && baseUrl) itemId = extractItemId(baseUrl);
if (!itemId && typeof chapter !== "undefined" && chapter && chapter.baseUrl) itemId = extractItemId(chapter.baseUrl);
if (!itemId) return "未找到章节ID";
var requestUrl = "https://m.wkbrowser.com/i" + itemId + "/info/v2/";
var responseJson;
var responseBody;
var content;
var payload;
var images;
var html;
var fullUrl;
var i;
try {
    responseBody = unwrapResponse(java.ajax(requestUrl));
    responseJson = JSON.parse(responseBody);
} catch (e2) {
    return "文章接口请求失败：" + (e2.message || String(e2));
}
if (!responseJson || !responseJson.data) return "未找到图片数据";
content = responseJson.data.content;
if (typeof content === "string" && content) {
    try {
        payload = JSON.parse(content);
    } catch (e3) {
        return "图片内容解析失败：" + (e3.message || String(e3));
    }
} else if (content && typeof content === "object") {
    payload = content;
} else {
    return "未找到图片内容";
}
images = collectImages(payload);
if (!images.length) return "未找到图片链接";
html = [];
for (i = 0; i < images.length; i++) {
    fullUrl = "https://p6-novel.byteimg.com/origin/" + images[i];
    html.push('<img src="' + fullUrl + '">');
}
return html.join("");
})()

